mapper.select:
select t.wordtemplateid,t.title,t.sort,t.flowid,f.flowname,pf.flowname as pflowname from pe_wordTemplate t left join PE_FLOW f on t.flowid=f.flowid left join PE_FLOW pf on f.parentId = pf.flowid where t.OperateState in ('A','M')
and t.title like concat('%',#{title},'%')
and t.flowid = #{flowid}
and f.parentId = #{pflowid}
order by t.sort
